import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"RFC-0015: Update Discovery — Channel Metadata and Device-Side Checking","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign-os/blob/main/docs/rfcs/0015-update-discovery.md"},"headers":[],"relativePath":"sovereign-os/rfcs/0015-update-discovery.md","filePath":"sovereign-os/rfcs/0015-update-discovery.md"}'),n={name:"sovereign-os/rfcs/0015-update-discovery.md"};function o(r,e,l,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="rfc-0015-update-discovery-—-channel-metadata-and-device-side-checking" tabindex="-1">RFC-0015: Update Discovery — Channel Metadata and Device-Side Checking <a class="header-anchor" href="#rfc-0015-update-discovery-—-channel-metadata-and-device-side-checking" aria-label="Permalink to &quot;RFC-0015: Update Discovery — Channel Metadata and Device-Side Checking&quot;">​</a></h1><p><strong>Status:</strong> Accepted <strong>Author:</strong> Project creator and Claude Sonnet 5 <strong>Created:</strong> 2026-08-01 <strong>Reviewers:</strong><strong>Target phase:</strong> Milestone 01.1, &quot;Update Discovery and Console Controls&quot; (ROADMAP item 3) <strong>Supersedes:</strong> None</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Give a device a way to learn &quot;a compatible update exists&quot; without an operator manually downloading and inspecting a release first. This RFC proposes the mechanism for that check — what gets published, where, how a device verifies and reports it — and explicitly does not propose a Console UI or an automatic install path. Both remain out of scope until Console has an authentication story (see <a href="./../adrs/0005-sovereign-console-and-health-boundary.html">ADR-0005</a>), per the project owner&#39;s own prior decision on that boundary.</p><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to &quot;Problem&quot;">​</a></h2><p>Every update this project has qualified so far — preview.9/10, preview.11/12, preview.13/14 — required an operator to already know a new version existed, download its manifest and artifact by hand, and run <code>sovereign-update prepare</code> themselves. There is no way for a device, or its owner, to find out a compatible update exists without already knowing to look. ROADMAP item 3&#39;s first two bullets name this directly: &quot;publish signed update-channel metadata over HTTPS&quot; and &quot;periodically check for compatible updates without sending household data.&quot;</p><p>A second, smaller problem this RFC surfaces: <strong>no release for this project has ever actually been published.</strong> <code>gh release list</code> shows only draft releases for <code>preview.1</code> through <code>preview.5</code>; every build since, including every version qualified this session, used <code>publish_draft_release: false</code>. Any discovery mechanism needs something real to check against, so this RFC also has to settle where that lives.</p><h2 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h2><ul><li>A device can determine, on its own schedule, whether a compatible update is available for its channel, without an operator triggering the check.</li><li>The check reuses the existing signed-manifest trust chain — it must not introduce a second, weaker way to claim &quot;this is a legitimate release.&quot;</li><li>The check sends nothing about the household beyond what&#39;s structurally necessary to identify compatible releases (device type, channel, current version) — no query history, no telemetry, no account.</li><li>Discovery is read-only: checking for an update never downloads the full artifact, stages anything, or mutates the device.</li><li>Results are visible locally (CLI, and — for a future slice — Console&#39;s read-only health surface) as &quot;notify,&quot; never &quot;install.&quot;</li></ul><h2 id="non-goals" tabindex="-1">Non-Goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to &quot;Non-Goals&quot;">​</a></h2><ul><li>Automatic download or installation. The ROADMAP&#39;s own policy for this milestone is explicit: <strong>notify and require approval</strong>. Automatic maintenance-window installation is a stated later step, gated on repeated field qualification, not part of this RFC.</li><li>Any Console UI or mutating trigger. Blocked on Console authentication, which this RFC does not attempt to solve.</li><li>A general release CDN, mirroring, or fleet-management concept. One project, one GitHub repository, public releases.</li><li>Changing how <code>prepare</code>/<code>backup</code>/<code>stage</code>/<code>activate</code> work. This RFC only adds a new, read-only <code>check</code> step before that existing flow.</li></ul><h2 id="context-and-evidence" tabindex="-1">Context and Evidence <a class="header-anchor" href="#context-and-evidence" aria-label="Permalink to &quot;Context and Evidence&quot;">​</a></h2><ul><li>The trust and verification chain already exists and is qualified: <code>inspect_update()</code> in <code>sovereign-update</code> verifies a manifest&#39;s signature against the local trust store, checks channel/device/version compatibility, and rejects downgrades — all without touching the filesystem beyond reading its inputs. See <a href="./0014-appliance-update-system.html">RFC-0014</a> and the qualification reports under <a href="./../research/"><code>docs/research/</code></a>.</li><li><code>sovereign-update-prune.timer</code> (this session) already establishes the pattern for a periodic, hardened, non-interactive systemd timer calling into <code>sovereign-update</code> — <code>check</code> can follow the same shape.</li><li>GitHub Releases is the only artifact host this project uses today (<code>scripts/create-update-release.py</code>, <code>.github/workflows/build-image.yml</code>). Every qualification this session downloaded manifests and bundles from either workflow-run artifacts or (in principle) release assets.</li><li>No channel concept beyond the <code>preview</code>/<code>stable</code> string already in the manifest schema exists. There is currently exactly one channel in active use (<code>preview</code>).</li></ul><h2 id="proposal" tabindex="-1">Proposal <a class="header-anchor" href="#proposal" aria-label="Permalink to &quot;Proposal&quot;">​</a></h2><h3 id="what-gets-published" tabindex="-1">What gets published <a class="header-anchor" href="#what-gets-published" aria-label="Permalink to &quot;What gets published&quot;">​</a></h3><p>No new artifact type. The existing signed <code>release-manifest.json</code> / <code>release-manifest.sig</code> pair, already produced by every build, <strong>is</strong> the channel metadata — this RFC does not invent a second document format for &quot;here&#39;s what&#39;s new.&quot; What changes is that a release intended for discovery must actually be published (non-draft) as a GitHub Release, with those two files (plus the update bundle and clean image) attached as release assets, tagged <code>v&lt;version&gt;</code> — matching the tagging convention <code>CONTRIBUTING.md</code> would need to document once this ships.</p><h3 id="how-a-device-finds-the-latest-one" tabindex="-1">How a device finds the latest one <a class="header-anchor" href="#how-a-device-finds-the-latest-one" aria-label="Permalink to &quot;How a device finds the latest one&quot;">​</a></h3><p><code>sovereign-update check</code> (new, read-only subcommand):</p><ol><li>Queries the GitHub REST API for this repository&#39;s releases (<code>GET /repos/sovereignfs/sovereign-os/releases</code>, unauthenticated — this is a public repository, and the endpoint doesn&#39;t require a token for read access at this volume).</li><li>Filters to non-draft releases whose tag parses as a valid version and whose asset list contains <code>release-manifest.json</code> and <code>release-manifest.sig</code>.</li><li>Selects the highest version compatible with the manifest&#39;s own declared <code>compatibility.source_versions</code> range for the device&#39;s <em>currently installed</em> version — not simply &quot;the newest tag&quot; — mirroring the same compatibility rule <code>prepare</code> already enforces.</li><li>Downloads only the two small manifest files for that release (not the multi-hundred-MB update bundle or image).</li><li>Runs the existing <code>inspect_update()</code> path against them — full signature and compatibility verification, zero new trust logic.</li><li>Reports the result — see Interfaces below — and does nothing else.</li></ol><h3 id="frequency-and-network-behavior" tabindex="-1">Frequency and network behavior <a class="header-anchor" href="#frequency-and-network-behavior" aria-label="Permalink to &quot;Frequency and network behavior&quot;">​</a></h3><ul><li>A new <code>sovereign-update-check.timer</code>, same shape as the prune timer: daily, jittered, <code>Persistent=true</code>.</li><li>Bounded timeouts and a bounded response size on every HTTP call — a malicious or broken endpoint must not be able to hang the timer or exhaust memory/disk.</li><li>Network failure (offline household, GitHub unreachable) is not an error state — it&#39;s logged and the device tries again next scheduled run. This must not affect <code>sovereign-update status</code>&#39;s own health reporting for the <em>installed</em> system.</li></ul><h2 id="interfaces-and-data-flow" tabindex="-1">Interfaces and Data Flow <a class="header-anchor" href="#interfaces-and-data-flow" aria-label="Permalink to &quot;Interfaces and Data Flow&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sovereign-update-check.timer (daily, jittered)</span></span>
<span class="line"><span>  -&gt; sovereign-update check</span></span>
<span class="line"><span>       -&gt; GET https://api.github.com/repos/sovereignfs/sovereign-os/releases</span></span>
<span class="line"><span>       -&gt; select highest compatible non-draft release</span></span>
<span class="line"><span>       -&gt; GET release-manifest.json + .sig for that release only</span></span>
<span class="line"><span>       -&gt; inspect_update() [existing, unchanged]</span></span>
<span class="line"><span>       -&gt; write /data/sovereign/update-state/update-check.json (atomic, like update-status.json)</span></span></code></pre></div><p><code>update-check.json</code> (schema sketch, not final):</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;schema_version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;checked_at&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-08-01T00:00:00Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;update_available&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;current_version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.1.0-preview.14&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;available_version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.1.0-preview.15&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;channel&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;preview&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;notes_url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://github.com/sovereignfs/sovereign-os/releases/tag/v0.1.0-preview.15&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;reboot_required&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>status</code> is one of <code>up_to_date</code>, <code>update_available</code>, or <code>check_failed</code> (with <code>error</code> populated only in that last case, and never containing anything beyond an internal error code — no raw HTTP bodies, no stack traces persisted).</p><p><code>sovereign-update status</code> (existing command) gains the check result as an additional read-only field, so <code>/api/v1/health</code>&#39;s existing <code>update</code> check can eventually surface &quot;an update is available&quot; — a small, additive change to an existing, already-qualified interface, not a new health check.</p><h2 id="security-and-privacy" tabindex="-1">Security and Privacy <a class="header-anchor" href="#security-and-privacy" aria-label="Permalink to &quot;Security and Privacy&quot;">​</a></h2><ul><li>The GitHub API call sends only what an unauthenticated HTTPS GET to a public repository&#39;s releases endpoint inherently sends — no device identifier, no household data, no query string beyond what the endpoint itself defines.</li><li>No new trust root. A release is only ever reported as &quot;available&quot; if it passes the exact same signature verification <code>prepare</code> already requires.</li><li><code>check</code> must not download or execute anything beyond the two small, independently-authenticated manifest files — it never fetches the multi-hundred-MB bundle.</li><li>TLS certificate verification is mandatory and not configurable off.</li><li><code>update-check.json</code> and the check log must not contain credentials, DNS query data, or household-identifying detail, matching the same rule already enforced for the transaction journal in <a href="./../../update/BACKUP_AND_JOURNAL.html">BACKUP_AND_JOURNAL.md</a>.</li></ul><h2 id="failure-and-recovery" tabindex="-1">Failure and Recovery <a class="header-anchor" href="#failure-and-recovery" aria-label="Permalink to &quot;Failure and Recovery&quot;">​</a></h2><ul><li>Every failure mode (network unreachable, malformed response, signature mismatch, rate-limited) writes <code>status: &quot;check_failed&quot;</code> with a bounded, non-secret error code and leaves the previous <code>update-check.json</code> result otherwise untouched — a transient failure must not erase yesterday&#39;s &quot;update available&quot; notice.</li><li><code>check</code> never touches <code>/opt/sovereign/releases/</code> or the update-transaction journal — a failed or interrupted check cannot leave the device in any state requiring <code>recover</code> or <code>discard</code>, because it never enters that state machine at all.</li></ul><h2 id="compatibility-and-migration" tabindex="-1">Compatibility and Migration <a class="header-anchor" href="#compatibility-and-migration" aria-label="Permalink to &quot;Compatibility and Migration&quot;">​</a></h2><ul><li>Purely additive: a new subcommand, a new timer, and a new field on an existing status file. No change to the <code>prepare</code>/<code>backup</code>/<code>stage</code>/ <code>activate</code> transaction flow, its schema, or its qualified behavior.</li><li>Devices that never run <code>check</code> (e.g. air-gapped, or before this ships) behave exactly as they do today.</li></ul><h2 id="operations-and-observability" tabindex="-1">Operations and Observability <a class="header-anchor" href="#operations-and-observability" aria-label="Permalink to &quot;Operations and Observability&quot;">​</a></h2><ul><li><code>sovereign-update check</code> is runnable manually, same as <code>prune</code>.</li><li>Journalctl output for <code>sovereign-update-check.service</code> follows the same convention as every other Sovereign systemd unit — human-readable, non-secret.</li><li>This RFC does not require publishing real (non-draft) releases as a <em>precondition of merging the code</em> — <code>check</code> degrades to <code>check_failed</code>/no compatible release found against an empty or all-draft release list, which is exactly today&#39;s actual state and is a legitimate, harmless outcome. Publishing real releases is a separate operational decision for the project owner, orthogonal to this RFC.</li></ul><h2 id="testing-strategy" tabindex="-1">Testing Strategy <a class="header-anchor" href="#testing-strategy" aria-label="Permalink to &quot;Testing Strategy&quot;">​</a></h2><ul><li>Unit tests against a fake HTTP transport (no real network calls in CI), covering: no releases published, only draft releases, a compatible release found, an incompatible-version release skipped, a signature-mismatched release rejected, malformed/oversized responses rejected, and a network-timeout path.</li><li>Hardware qualification once a real non-draft release exists to check against — deferred until that publishing decision is made, matching how every other command in this project got unit-tested first and hardware-qualified once real conditions existed to test it against.</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives Considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives Considered&quot;">​</a></h2><h3 id="a-dedicated-channel-metadata-document-separate-from-release-manifests" tabindex="-1">A dedicated channel-metadata document, separate from release manifests <a class="header-anchor" href="#a-dedicated-channel-metadata-document-separate-from-release-manifests" aria-label="Permalink to &quot;A dedicated channel-metadata document, separate from release manifests&quot;">​</a></h3><p>Publish a small <code>channel-preview.json</code> pointer file (version + manifest URL) instead of listing GitHub releases directly. Rejected for v1: it adds a second document to keep in sync with every release, a second thing to sign, and a second place trust can drift, for no benefit over querying GitHub Releases directly while there is exactly one channel and one publisher. Worth revisiting if this project ever needs a release host other than GitHub, or per-channel metadata GitHub&#39;s API can&#39;t express.</p><h3 id="poll-a-self-hosted-or-third-party-update-metadata-service" tabindex="-1">Poll a self-hosted or third-party update-metadata service <a class="header-anchor" href="#poll-a-self-hosted-or-third-party-update-metadata-service" aria-label="Permalink to &quot;Poll a self-hosted or third-party update-metadata service&quot;">​</a></h3><p>Rejected outright — directly contradicts the project&#39;s self-hosted, no-mandatory-third-party-dependency values, and GitHub Releases already serves this exact purpose for free on a public repository.</p><h2 id="drawbacks-and-maintenance-cost" tabindex="-1">Drawbacks and Maintenance Cost <a class="header-anchor" href="#drawbacks-and-maintenance-cost" aria-label="Permalink to &quot;Drawbacks and Maintenance Cost&quot;">​</a></h2><ul><li>A new outbound network dependency (GitHub&#39;s API) on a device that otherwise needs no internet access for its core DNS function. Framed and gated as strictly opt-in-by-default-off until this RFC is accepted and the timer is actually enabled in a shipped image.</li><li>GitHub API rate limits for unauthenticated requests are per-source-IP, not per-device from GitHub&#39;s point of view if many devices share a household&#39;s public IP — unlikely to matter at today&#39;s scale, but worth naming.</li></ul><h2 id="unresolved-questions" tabindex="-1">Unresolved Questions <a class="header-anchor" href="#unresolved-questions" aria-label="Permalink to &quot;Unresolved Questions&quot;">​</a></h2><ul><li>Should <code>channel</code> in the device&#39;s <code>update-policy.json</code> gain an explicit opt-out for <code>check</code> entirely (fully air-gapped households)? Leaning yes, deferred to implementation.</li><li>Exact retry/backoff behavior on GitHub rate-limiting vs. genuine failure — needs a decision during implementation, not this RFC.</li><li>When (not if) real non-draft releases start being published, does that become part of the existing <code>build-image.yml</code> workflow&#39;s normal path, or a separate manual promotion step? Release-process question, not an architecture question — recommend deciding alongside production signing-key generation (ADR-0006), since both are needed together before this is meaningfully usable end to end.</li></ul><h2 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h2><ul><li><code>sovereign-update check</code> and <code>sovereign-update-check.timer</code> implemented, unit-tested per the Testing Strategy above.</li><li><code>sovereign-update status</code> includes the last check result.</li><li>No change to any existing command&#39;s behavior or exit codes.</li><li>Documented in <code>update/README.md</code> and cross-linked from <code>docs/operations/update-recovery-and-compatibility.md</code>.</li><li>Explicitly does not require a Console change or a production signing key to merge — both remain separately gated as described above.</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Accepted by the project owner on 2026-08-01, as scoped: device-side check-and-notify only, no Console change, no production signing key required to merge. Publishing real (non-draft) releases and the exact retry/backoff and air-gap opt-out details are left to implementation, per the Unresolved Questions above.</p>`,50)])])}const g=a(n,[["render",o]]);export{p as __pageData,g as default};
